	if err != nil {
		return nil, err
	}
	switch discriminator {
	case "anthropic":
		return t.AsAnthropicBackendOptions()
	case "google":
		return t.AsGoogleBackendOptions()
	case "openai":
		return t.AsOpenAIBackendOptions()
	default:
		return nil, errors.New("unknown discriminator value: " + discriminator)
	}
